"""Build RetroBoot's bundled Platinum chrome without guest media."""
from base64 import b64encode
import json
from pathlib import Path

from . import chrome
from .canvas import LAVENDER, PURPLE, Palette
from .image import rbi


def build(out: Path | None, web_css: Path | None) -> None:
    palette = {
        "ramp": ["#%02x%02x%02x" % color for color in LAVENDER],
        "highlight": "#%02x%02x%02x" % PURPLE,
    }
    sprites = {}
    css = [
        "/* Generated by python3 -m rbplatinum builtin. RetroBoot artwork. */",
        ":root {",
        *(f"  --pt-ramp-{i}: {color};" for i, color in enumerate(palette["ramp"])),
        f'  --pt-highlight: {palette["highlight"]};',
    ]
    if out:
        (out / "chrome").mkdir(parents=True, exist_ok=True)

    def put(name, canvas, **meta):
        img = canvas.image()
        if out:
            rel = f"chrome/{name}.rbi"
            (out / rel).write_bytes(rbi(img))
            sprites[name] = {"rbi": rel, **meta}
        if web_css:
            png = b64encode(img.png()).decode("ascii")
            css.append(f'  --pt-{name}: url("data:image/png;base64,{png}");')

    chrome.draw_theme(Palette(LAVENDER, PURPLE, extra=chrome.ALERT_COLORS), put)
    if out:
        manifest = {"format": 1, "palette": palette, "chrome": sprites}
        (out / "manifest.json").write_text(json.dumps(manifest, indent=2) + "\n", encoding="utf-8")
    if web_css:
        web_css.parent.mkdir(parents=True, exist_ok=True)
        web_css.write_text("\n".join([*css, "}", ""]), encoding="utf-8")
